        #region TrnForm24QSalaryDetails_Load
        private void TrnForm24QSalaryDetails_Load(object sender, EventArgs e)
        {
            GC.Collect();
            //
            //-----------------------------------------------------------
            lblTitle.Text = "Form " + T_FormNo.F24Q + " Salary Details";
            //-----------------------------------------------------------                
            txtFinancialYear.Text = TDSMAN.Classes.TDSMAN.T_pFinancialYear;
            txtQuarter.Text = TDSMAN.Classes.TDSMAN.T_pQuarter;
            txtCompany.Text = TDSMAN.Classes.TDSMAN.T_pCompanyName;
            //ADDED BY @@DHRUB --2015-08-11
            txtFAYearID.Text = TDSMAN.Classes.TDSMAN.T_pFinancialYearId.ToString();
            //
            if (TDSMAN.Classes.TDSMAN.T_pEditionType == T_EDITION_TYPE.STANDARD_EDITION)
            {
                strExcelActivateButtonCaption = "Add data using Excel";
                btnExcelActivate.Text = strExcelActivateButtonCaption;
                rbnModifyDeductees.Visible = false;
                rbnAddDeductees.Visible = false;
                pnlLine1.Visible = false;
                grpModifyDeductees.Visible = false;
            }
            //-- 2019/05/05
            pnlImportExcelFile.Location = new Point(12, 82);
            //
            ClearControlsHeader();
            //
            txtEmployeeName.Select();
            //
            mskEmployeeFromDate.Text = TdsMan.T_ReturnStartDateFinancialYear(txtFinancialYear.Text);
            mskEmployeeToDate.Text = TdsMan.T_ReturnEndDateFinancialYear(txtFinancialYear.Text);
            //-----------------------------------------------------------
            lblMode.Text = J_Mode.View;
            cmnService.J_StatusButton(this, lblMode.Text);
            //
            BtnAdd_Click(sender, e);
            //
            //## ANIK 2013/04/26
            if (TDSMAN.Classes.TDSMAN.T_pFinancialYearId == T_FinancialYearID.F2010_11ID ||
                    TDSMAN.Classes.TDSMAN.T_pFinancialYearId == T_FinancialYearID.F2011_12ID)
            {
                lblCaption80CC.Text = "Total Deductible Amount (80CCF)";
            }
            else if (TDSMAN.Classes.TDSMAN.T_pFinancialYearId >= T_FinancialYearID.F2012_13ID)
            {
                lblCaption80CC.Text = "Total Deductible Amount (80CCG)";
            }
            //##
            if (TDSMAN.Classes.TDSMAN.T_pFinancialYearId >= T_FinancialYearID.F2013_14ID)
            {
                grpSalaryBreakup.Visible = true;
                grpTDSBreakup.Visible = true;
                //-- 2016/09/22
                grpSuperannuationFund.Visible = true;
                //-- 2017/04/11
                if (TDSMAN.Classes.TDSMAN.T_pFinancialYearId >= T_FinancialYearID.F2016_17ID)
                {
                    grpRent.Visible = true;
                    grpHouseProperty.Visible = true;
                }
            }
            else
            {
                grpSalaryBreakup.Visible = false;
                grpTDSBreakup.Visible = false;
                //--
                grpDeductionsUS16.Location = new Point(grpDeductionsUS16.Location.X, grpDeductionsUS16.Location.Y - 82);
                lblIncomeChargeableDesc.Location = new Point(lblIncomeChargeableDesc.Location.X, lblIncomeChargeableDesc.Location.Y - 82);
                lblIncomeChargeable.Location = new Point(lblIncomeChargeable.Location.X, lblIncomeChargeable.Location.Y - 82);
                lblOtherIncomeDesc.Location = new Point(lblOtherIncomeDesc.Location.X, lblOtherIncomeDesc.Location.Y - 82);
                txtOtherIncome.Location = new Point(txtOtherIncome.Location.X, txtOtherIncome.Location.Y - 82);
                lblGrossTotalIncomeDesc.Location = new Point(lblGrossTotalIncomeDesc.Location.X, lblGrossTotalIncomeDesc.Location.Y - 82);
                lblGrossTotalIncome.Location = new Point(lblGrossTotalIncome.Location.X, lblGrossTotalIncome.Location.Y - 82);
                grpDedcutionsUCVIA.Location = new Point(grpDedcutionsUCVIA.Location.X, grpDedcutionsUCVIA.Location.Y - 82);
                lblTotalIncomeDesc.Location = new Point(lblTotalIncomeDesc.Location.X, lblTotalIncomeDesc.Location.Y - 82);
                lblTotalIncome.Location = new Point(lblTotalIncome.Location.X, lblTotalIncome.Location.Y - 82);
                grpTaxPayable.Location = new Point(grpTaxPayable.Location.X, grpTaxPayable.Location.Y - 82);
                lblShortfallDesc.Location = new Point(lblShortfallDesc.Location.X, lblShortfallDesc.Location.Y - 70);
                lblShortfall.Location = new Point(lblShortfall.Location.X, lblShortfall.Location.Y - 70);
                //pnlSalaryDetailsEntryForm.Height = 450;
                lblHigherRateDesc.Location = new Point(lblHigherRateDesc.Location.X, lblHigherRateDesc.Location.Y - 70);
                cmbHigherRate.Location = new Point(cmbHigherRate.Location.X, cmbHigherRate.Location.Y - 70);
                grpTaxPayable.Height = 285;
                //--
                grpSuperannuationFund.Visible = false;
            }
            //--
            //-----------------------------------------------
            //-----------------------------------------------
            lngBatchId = TDSMAN.Classes.TDSMAN.T_pBatchId; //TdsMan.T_ReturnBasicInfoId(dmlService.J_pCommand, TDSMAN.Classes.TDSMAN.T_pFinancialYearId,
            //TDSMAN.Classes.TDSMAN.T_pQuarter,
            //TDSMAN.Classes.TDSMAN.T_pCompanyId,
            //TDSMAN.Classes.TDSMAN.T_pFormNo);
            if (lngBatchId > 0)
            {
                LoadSalaryDetailsGrid(lngBatchId);
                //-- Generate Salary Detail Srl No.
                txtSalaryDetailSrlNo.Text = Convert.ToString(dmlService.J_ReturnMaxValue("COR_TRN_SALARY_DETAILS", "SL_NO", "BATCH_HEADER_ID = " + lngBatchId + "") + 1);
            }
            else
                txtSalaryDetailSrlNo.Text = "1";
            //
            BtnDelete.Enabled = false;
            BtnDelete.BackColor = Color.LightGray;
            //-- 2019/04/04 && 2019/05/05
            if (TDSMAN.Classes.TDSMAN.T_pFinancialYearId >= T_FinancialYearID.F2018_19ID)
            {
                lblEducationCessDesc.Text = "Education Cess @ 4%";
                lblSec16ia.Visible = true;
                txtDedStdDeduction.Visible = true;
                lblAggregate4_a_bDesc.Text = "Aggregate of (a), (b) && (c)";
                //-- 2019/05/05
                grpGrossSalary.Enabled = true;
                grpLessAllowanceUS101819.Enabled = true;
                grpAddOtherIncome.Enabled = true;
                lblOtherIncomeDesc.Enabled = false;
                txtOtherIncome.Enabled = false;
                grpDedcutionsUCVIA1819.Enabled = true;
                grpDedcutionsUCVIA.Enabled = false;
                //--
                txtOtherIncomeDesc1.Text = "INCOME / LOSS - HOUSE PROPERTY OFFERED FOR TDS";
                txtOtherIncomeDesc1.ReadOnly = true;
                txtOtherIncomeDesc1.TabStop = false;
                txtOtherIncomeDesc2.Text = "INCOME-OTHER SOURCES OFFERED FOR TDS";
                txtOtherIncomeDesc2.ReadOnly = true;
                txtOtherIncomeDesc2.TabStop = false;
            }
            else
            {
                lblEducationCessDesc.Text = "Education Cess @ 3%";
                lblSec16ia.Visible = false;
                txtDedStdDeduction.Visible = false;
                lblAggregate4_a_bDesc.Text = "Aggregate of (a) && (b)";
                //-- 2019/05/05
                grpGrossSalary.Enabled = false;
                grpLessAllowanceUS101819.Enabled = false;
                grpAddOtherIncome.Enabled = false;
                lblOtherIncomeDesc.Enabled = true;
                txtOtherIncome.Enabled = true;
                grpDedcutionsUCVIA1819.Enabled = false;
                grpDedcutionsUCVIA.Enabled = true;
                //--
                txtOtherIncomeDesc1.Text = "";
                txtOtherIncomeDesc1.ReadOnly = false;
                txtOtherIncomeDesc1.TabStop = true;
                txtOtherIncomeDesc2.Text = "";
                txtOtherIncomeDesc2.ReadOnly = false;
                txtOtherIncomeDesc2.TabStop = true;
            }
            //--
            //ADDED BY @@DHRUB -- 2015-08-14
            blnIncrementalImport = true;
        }
