        #region btnCreateBlankExcelFile_Click
        private void btnCreateBlankExcelFile_Click(object sender, EventArgs e)
        {
            try
            {
                //--------------------------------------------------------------------------------------------------
                string strExcelFileName = "";           //-- FOR EXCEL FILE NAME INTO APPLICATION PATH
                string strOutputExcelFileName = "";     //-- FOR OUTPUT EXCEL FILE NAME INTO SELECTED PATH BY USER 
                string strExcelFieldAsciiAfterZ = "";   //--
                //--
                bool blnExcelFieldAsciiAfterZ = false;  //-- FOR EXCEL INITIAL CELL VALUE A 
                //--
                int intIncrement = 0;                   //-- FOR LOOPING INCREMENTAL VARIABLE
                int intColumn;                          //-- FOR EXCEL COLUMN
                int intRow;                             //-- FOR EXCEL ROW
                string strOriginalExcelFileName = "";   //-- FOR EXCEL FILE NAME
                //--------------------------------------------------------------------------------------------------
                //--
                //if (cmnService.J_UserMessage("Proceed??", MessageBoxButtons.YesNo) == DialogResult.No)
                //    return;
                //--
                //-- INITIALIZE THE DESTINATION PATH OF OUTPUT EXCEL 
                string strDestFilePath = cmnService.J_OpenFolderDialog();
                //--
                if (strDestFilePath != "")
                {
                    //--
                    this.Cursor = Cursors.WaitCursor;
                    //--
                    //-- Added By Abhishek Dey On 21/07/2018 --
                    if (rbnModifyDeductees.Checked == true)
                    {
                        if (rbnPANModificationDD.Checked == true)
                        {
                            strExcelFileName = "SD_MODIFY_PAN";
                            strOriginalExcelFileName = strExcelFileName;
                        }
                        else
                        { }

                        //--
                        //Creating a different filename if file with same name exists in the selected folder
                        do
                        {
                            ExcelFileName = strExcelFileName; //Default Filename
                            if (cmnService.J_IsFileExist(Path.Combine(strDestFilePath, ExcelFileName + ".xls")) == true || cmnService.J_IsFileExist(Path.Combine(strDestFilePath, ExcelFileName + ".xlsx")))
                            {
                                intIncrement++;
                                ExcelFileName = ExcelFileName + " (" + intIncrement + ") ";
                            }

                        } while (cmnService.J_IsFileExist(Path.Combine(strDestFilePath, ExcelFileName + ".xls")) == true || cmnService.J_IsFileExist(Path.Combine(strDestFilePath, ExcelFileName + ".xlsx")) == true);
                        //--
                        strDestFile = ExcelFileName;
                    }
                    //-----------------------------------------
                    //
                    else
                    {
                        strOutputExcelFileName = strExcelFileCaptionText + txtFinancialYear.Text;
                        //--
                        //----------------------------------------------------------------------------------------
                        //Creating a different filename if file with same name exists in the selected folder
                        //----------------------------------------------------------------------------------------
                        do
                        {
                            if (cmnService.J_IsFileExist(Path.Combine(strDestFilePath, strOutputExcelFileName + ".xls")) == true)
                            {
                                intIncrement++;
                                strOutputExcelFileName = strExcelFileCaptionText + txtFinancialYear.Text + " (" + intIncrement + ")";
                            }

                        } while (cmnService.J_IsFileExist(Path.Combine(strDestFilePath, strOutputExcelFileName + ".xls")) == true);
                        //--
