                            //strExcelFileName = strExcelFileCaptionText + T_FinancialYear.F2013_14 + ".xls";                        
                            if (Convert.ToInt32(txtFAYearID.Text) >= (int)T_FinancialYearID.F2016_17ID)
                                strExcelFileName = strExcelFileCaptionText + T_FinancialYear.F2016_17 + ".xls";
                            else
                                strExcelFileName = strExcelFileCaptionText + T_FinancialYear.F2013_14 + ".xls";
                        }
                        else
                            strExcelFileName = strExcelFileCaptionText + T_FinancialYear.F2012_13 + ".xls";
                    }
                    //-- Added By Abhishek Dey On 21/07/2018 --
                    if (Path.GetExtension(strExcelFileName).ToUpper() != ".XLS" || Path.GetExtension(strExcelFileName).ToUpper() != ".XLSX")
                    {
                        strExcelFileName = strExcelFileName + ".xls";
                    }
