        #region btnImport_Click
        private void btnImport_Click(object sender, EventArgs e)
        {
            try
            {
                //-- Added By Abhishek Dey On 25/07/2018 --
                if (btnImport.Text == strImportText)
                {
                    prgImportBar.Value = 0;
                    //
                    #region MODIFY PAN
                    if (rbnPANModificationDD.Checked == true)
                    {
                        try   //-- Added By Abhishek Dey On 30/08/2018 --
                        {
                            bool isModifyAllChallan = false; //-- Added By Abhishek Dey On 30/08/2018 --
                            //
                            DataSet dsPan = new DataSet();
                            strSQL1 = "SELECT * FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SD_MODIFY_PAN;
                            dsPan = dmlService.J_ExecSqlReturnDataSet(strSQL1);
                            //
                            //-- Added By Abhishek Dey On 30/08/2018 --
                            //if (chkPANModify.Checked == true)
                            //{
                            //    if (cmnService.J_UserMessage("This will also modify the PAN(s) matching in other records of this return.\nClick Yes to proceed or No to modify only the records matched by Excel??", MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes)
                            //    {
                            //        isModifyAllChallan = true;
                            //    }
                            //    else
                            //    {
                            //        isModifyAllChallan = false;
                            //    }
                            //}
                            //else
                            //    isModifyAllChallan = false;
                            //----------------------------------------
                            //
                            foreach (DataRow drPan in dsPan.Tables[0].Rows)
                            {
                                if (Convert.ToInt32(drPan["SD_SERIAL_NO"].ToString()) > 0)
                                {
                                    strSQL1 = "UPDATE COR_TRN_SALARY_DETAILS SET " +
                                              "       PAN_UPDATION_INDICATOR = " + T_UPDATION_INDICATOR.ON + ", " +
                                              "       EMPLOYEE_PAN = '" + Convert.ToString(drPan["NEW_PAN"].ToString()) + "' " +
                                              " WHERE IMPORT_FLAG            = 1 " +
                                              "   AND SL_NO                  = " + Convert.ToInt32(drPan["SD_SERIAL_NO"].ToString()) + " " +
                                              "   AND BATCH_HEADER_ID        = " + lngBatchId + " " +
                                              "   AND EMPLOYEE_PAN           = '" + Convert.ToString(drPan["PAN_OF_EMPLOYEE"].ToString()) + "' ";

                                    if (dmlService.J_ExecSql(strSQL1) == false)
                                    {
                                        return;
                                    }
                                    //--

                                    // UPDATE PAN UPDATION INDICATOR
                                    strSQL1 = @" SELECT TRN_SALARY_DETAILS_ID,
                                                        HDR_SALARY_DETAILS_ID
                                                   FROM COR_TRN_SALARY_DETAILS
                                                  WHERE   IMPORT_FLAG            = 1 " +
                                                "   AND   SL_NO                  = " + Convert.ToInt32(drPan["SD_SERIAL_NO"].ToString()) + " " +
                                                "   AND   BATCH_HEADER_ID        = " + lngBatchId + " " +
                                                "   AND   EMPLOYEE_PAN           = '" + Convert.ToString(drPan["NEW_PAN"].ToString()) + "' ";

                                    DataSet dsEmployee = dmlService.J_ExecSqlReturnDataSet(strSQL1);
                                    //
                                    strSQL1 = @" SELECT EMPLOYEE_PAN FROM COR_HDR_SALARY_DETAILS WHERE HDR_SALARY_DETAILS_ID = " + Convert.ToInt32(dsEmployee.Tables[0].Rows[0]["HDR_SALARY_DETAILS_ID"].ToString());
                                    string strPAN = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL1));
                                    //
                                    if (string.Compare(drPan["NEW_PAN"].ToString(), strPAN) == 0)
                                    {
                                        strSQL1 = @" UPDATE COR_TRN_SALARY_DETAILS SET " +
                                                   "        PAN_UPDATION_INDICATOR = " + T_UPDATION_INDICATOR.OFF + " " + @"
                                                 WHERE  TRN_SALARY_DETAILS_ID  =  " + Convert.ToInt32(dsEmployee.Tables[0].Rows[0]["TRN_SALARY_DETAILS_ID"].ToString());

                                        if (dmlService.J_ExecSql(strSQL1) == false)
                                        {
                                            return;
                                        }

                                    }
                                    //--

                                }
                                //-- 05/09/2018 --
                                // IF SD_SERIAL_NO DOES NOT EXISTS
                                else
                                {
                                    if (string.Compare(drPan["PAN_OF_EMPLOYEE"].ToString(), "PANNOTAVBL") == 0)
                                    {
                                        // SALARY DETAILS
                                        strSQL1 = "UPDATE COR_TRN_SALARY_DETAILS SET " +
                                                            "       PAN_UPDATION_INDICATOR = " + T_UPDATION_INDICATOR.ON + ", " +
                                                            "       EMPLOYEE_PAN = '" + Convert.ToString(drPan["NEW_PAN"].ToString()) + "' " +
                                                            "   WHERE  IMPORT_FLAG            = 1 " +
                                                            "    AND   BATCH_HEADER_ID        = " + lngBatchId + " " +
                                                            "    AND   EMPLOYEE_PAN           = '" + Convert.ToString(drPan["PAN_OF_EMPLOYEE"].ToString()) + "' " +
                                                            "    AND   EMPLOYEE_NAME          = '" + Convert.ToString(drPan["NAME_OF_EMPLOYEE"].ToString()) + "' " +  //-- 18/09/2018 --
                                                            "    AND   MODE                   <> 'D' ";  //-- Added By Abhishek Dey On 11/09/2018 --

                                        if (dmlService.J_ExecSql(strSQL1) == false)
                                        {
                                            return;
                                        }
