                    //-- Added By Abhishek Dey On 10/10/2018 --
                    #region Bulk Deletion

                    if (rbnBulkDeletion.Checked == true)
                    {
                        try
                        {
                            prgImportBar.Value = 0;
                            DataSet dsBulkDelete = new DataSet();
                            DataSet dsDetails = new DataSet();
                            strSQL1 = "SELECT * FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SD_DELETE;
                            dsBulkDelete = dmlService.J_ExecSqlReturnDataSet(strSQL1);
                            prgImportBar.Value = prgImportBar.Value + 10;  //-- 05/10/2018 --
                            int i = 0;

                            if (dsBulkDelete.Tables[0].Rows.Count > 0)
                            {
                                foreach (DataRow drBulkDelete in dsBulkDelete.Tables[0].Rows)
                                {
                                    strSQL1 = " UPDATE COR_TRN_SALARY_DETAILS " +
                                             " INNER JOIN COR_HDR_SALARY_DETAILS " +
                                             "        ON  COR_TRN_SALARY_DETAILS.HDR_SALARY_DETAILS_ID = " +
                                             "            COR_HDR_SALARY_DETAILS.HDR_SALARY_DETAILS_ID " +
                                             " SET    COR_TRN_SALARY_DETAILS.MODE                   = '" + T_CorrectionMode.Delete + "', " +
                                             "        COR_TRN_SALARY_DETAILS.EMPLOYEE_PAN           = COR_HDR_SALARY_DETAILS.EMPLOYEE_PAN, " +
                                             "        COR_TRN_SALARY_DETAILS.PAN_UPDATION_INDICATOR =  " + T_UPDATION_INDICATOR.OFF + " " +
                                             " WHERE  COR_TRN_SALARY_DETAILS.BATCH_HEADER_ID        = " + lngBatchId + " " +
                                             "   AND  COR_TRN_SALARY_DETAILS.SL_NO                  = " + drBulkDelete["SD_SERIAL_NO"].ToString() + " " +
                                             "   AND  COR_TRN_SALARY_DETAILS.EMPLOYEE_PAN           = '" + drBulkDelete["PAN_OF_EMPLOYEE"].ToString() + "' ";

                                    if (dmlService.J_ExecSql(strSQL1) == false)
                                    {
                                        lblMode.Text = J_Mode.Add;
                                        //txtDeducteeName.Select();
                                        return;
                                    }

                                }
                            }
                            else
                            {
                                cmnService.J_UserMessage("No records found!", MessageBoxButtons.OK, MessageBoxIcon.Error);
                                prgImportBar.Value = 0;

                                return;
                            }
                        }
                        catch (Exception err_handler)
                        {
                            cmnService.J_UserMessage(err_handler.Message);
                        }
                    }

                    #endregion
                    //-----------------------------------------
                }
                else
                {
                    //string strMessage = "Incremental import";
                    //--
                    if (cmnService.J_UserMessage("Excel Import based on - \n " +
                            "FINANCIAL YEAR \t: " + txtFinancialYear.Text + " \n " +
                            "COMPANY  \t: " + txtCompany.Text + " \n " +
                            "Proceed??", MessageBoxButtons.YesNo) == DialogResult.No)
                        return;
                    //--
                    prgImportBar.Value = 0;
                    //--
                    this.Cursor = Cursors.WaitCursor;
                    //--                
                    prgImportBar.Value = prgImportBar.Value + 5;
                    this.Refresh();
                    //--
                    if (INSERT_SALARY_DATA(lngBatchId) == false)
                    {
                        cmnService.J_UserMessage("Import failed", MessageBoxIcon.Error);
                        this.Cursor = Cursors.Default;
                        return;
                    }
                    //
                    prgImportBar.Value = prgImportBar.Value + 5;
                    this.Refresh();
                    //--
                    if (DROP_TEMP_TABLES() == false)
                    {
                        cmnService.J_UserMessage("Import failed", MessageBoxIcon.Error);
                        this.Cursor = Cursors.Default;
                        return;
                    }
                }
                this.Refresh();
                //--
                for (int i = prgImportBar.Minimum; i <= prgImportBar.Maximum; i++)
                {
                    prgImportBar.PerformStep();
                }
                //
                this.Cursor = Cursors.Default;
                //--
                //---------------------------------------------------------
                if (rbnPANModificationDD.Checked == true)  //-- Added By Abhishek Dey On 26/07/2018 --
                    cmnService.J_UserMessage("PAN modification successfully.", MessageBoxIcon.Information);    //-- Added By Abhishek Dey On 28/07/2018 --
                else if (rbnBulkDeletion.Checked == true)  //-- Added By Abhishek Dey On 11/10/2018 --
                    cmnService.J_UserMessage("Bulk deletion completed successfully", MessageBoxIcon.Information);
                else
                    cmnService.J_UserMessage("Import from Excel File completed", MessageBoxIcon.Information);
                //--
                prgImportBar.Value = 0;
                btnBackToSalaryDetails_Click(sender, e);
                //--
            }
            catch(Exception Err)
            {
                cmnService.J_UserMessage(Err.Message);
                return;
            }
        }
        #endregion

