        #region dgcViewSalaryDetails_Click
        private void dgcViewSalaryDetails_Click(object sender, EventArgs e)
        {
            //Added by Indrajit on 04-03-2013
            //if (dsetGridClone.Tables[0].Rows.Count == 0) return;
            if (dgcViewSalaryDetails.CurrentRow == null) return;

            if (Convert.ToInt64(dgcViewSalaryDetails.CurrentRow.Index) < 0)
            {
                BtnAdd.Focus();
                return;
            }

            if (lblMode.Text != J_Mode.Edit)
                lngSearchId = Convert.ToInt64(dgcViewSalaryDetails.Rows[dgcViewSalaryDetails.CurrentRow.Index].Cells[0].Value);
            
            if (lngSearchId > 0)
            {
                if (lblMode.Text == J_Mode.Add)
                {
                    //
                    BtnEdit.Enabled = true;
                    BtnEdit.BackColor = Color.Lavender;
                    //
                    BtnDelete.Enabled = true;
                    BtnDelete.BackColor = Color.Lavender;


                    strSQL = "SELECT MODE FROM COR_TRN_SALARY_DETAILS WHERE TRN_SALARY_DETAILS_ID = " + lngSearchId;
                    //----------------------------------
                    //-- ADDED BY DHRUB @@2015-08-21
                    //----------------------------------
                    string strQueryString = "SELECT PAN_UPDATION_INDICATOR FROM COR_TRN_SALARY_DETAILS WHERE TRN_SALARY_DETAILS_ID = " + lngSearchId;
                    //--------------------------------------------------------------------------------------------------
                    //-- MODIFIED BY @@DHRUB--2015-08-20 TO RESTORE WHEN
                    //--------------------------------------------------------------------------------------------------
                    //-- MODE - > DELETE
                    //-- PAN_UPDATE_INDICATOR - > 1
                    //--------------------------------------------------------------------------------------------------
                    if (Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)) == T_CorrectionMode.Delete ||
                        Convert.ToInt32(dmlService.J_ExecSqlReturnScalar(strQueryString)) == T_UPDATION_INDICATOR.ON)
                        BtnDelete.Text = T_DeleteRestoreText.Restore;
                    else
                        BtnDelete.Text = T_DeleteRestoreText.Delete;
                }
            }
            else
            {
                BtnEdit.Enabled = false;
                BtnEdit.BackColor = Color.LightGray;
            }

        }
        #endregion

        #region dgcViewSalaryDetails_KeyDown
        private void dgcViewSalaryDetails_KeyDown(object sender, KeyEventArgs e)
        {
            if (dgcViewSalaryDetails.CurrentRow.Index < 0) return;

            lngSearchId = Convert.ToInt64(dgcViewSalaryDetails.Rows[dgcViewSalaryDetails.CurrentRow.Index].Cells[0].Value);

            if (e.KeyCode == Keys.Enter) dgcViewSalaryDetails_DoubleClick(sender, e);

            if (e.KeyCode == Keys.Delete) BtnDelete_Click(sender, e);

        }
        #endregion

        #region dgcViewSalaryDetails_DoubleClick
        private void dgcViewSalaryDetails_DoubleClick(object sender, EventArgs e)
        {
            //Added by Indrajit on 04-03-2013
            //if (dsetGridClone.Tables[0].Rows.Count == 0) return;
            BtnEdit_Click(sender, e);
        }
        #endregion

        #region dgcViewSalaryDetails_CurrentCellChanged
        private void dgcViewSalaryDetails_CurrentCellChanged(object sender, EventArgs e)
        {
            if (dgcViewSalaryDetails.CurrentRow == null) return;
            dgcViewSalaryDetails_Click(sender, e);
        }
        #endregion

        #region dgcViewSalaryDetails_CellFormatting
        private void dgcViewSalaryDetails_CellFormatting(object sender, DataGridViewCellFormattingEventArgs e)
        {
            try
            {
                #region CellFormatting(DEDUCTEE_PAN)

                if (dgcViewSalaryDetails.Columns[e.ColumnIndex].DataPropertyName == "EMPLOYEE_PAN")
                {
                    //CHECKING THE INVALID PAN FLAG FOR THIS PAN
                    if (dgcViewSalaryDetails.Rows[e.RowIndex].Cells["INVALID_PAN"].Value.ToString() == "1")
                    {
                        //PAN IS INVALID

                        //NOW CHECKING IF THE PAN HAS BEEN MODIFIED OR THE RECORD HAS BEEN DELETED

                        if (dgcViewSalaryDetails.Rows[e.RowIndex].Cells["PAN_UPDATION_INDICATOR"].Value.ToString() != "1" &&
                            dgcViewSalaryDetails.Rows[e.RowIndex].Cells["MODE"].Value.ToString() != "Del")
                        {
                            //PAN HAS NOT BEEN MODIFIED AND HAS NOT BEEN DELETED

                            //NOW HIGHLIGHLING THE CELL 
                            //highlighting the cell
                            //e.CellStyle.BackColor = Color.FromArgb(231, 206, 248); //PURPLE COLOR
                            e.CellStyle.BackColor = Color.Red;
                            e.CellStyle.ForeColor = Color.White;

                            if (e.Value.ToString() == "PANNOTAVBL")
                                dgcViewSalaryDetails.Rows[e.RowIndex].Cells[e.ColumnIndex].ToolTipText = "Enter the Valid PAN if now available";
                            else if (e.Value.ToString() == "PANINVALID")
                                dgcViewSalaryDetails.Rows[e.RowIndex].Cells[e.ColumnIndex].ToolTipText = "Enter the Valid PAN if now available";
                            else if (e.Value.ToString() == "PANAPPLIED")
                                dgcViewSalaryDetails.Rows[e.RowIndex].Cells[e.ColumnIndex].ToolTipText = "Enter the Valid PAN if now available";
                            else
                                dgcViewSalaryDetails.Rows[e.RowIndex].Cells[e.ColumnIndex].ToolTipText = "This PAN (" + e.Value.ToString() + ") has been marked \nInvalid by the Income Tax Department";
                        }
                    }
                }
                #endregion

                #region CellFormatting(MODE)
                if (dgcViewSalaryDetails.Columns[e.ColumnIndex].DataPropertyName == "MODE")
                {
                    if (e.Value.ToString() == "Upd")
                    {

                        #region Highlighting cell for Update record

                        // ----------------------------------------------
                        // -- HIGHLIGHTING THE UPDATE MODE CELL
                        // ----------------------------------------------

                        e.CellStyle.BackColor = Color.Yellow;
                        dgcViewSalaryDetails.Rows[e.RowIndex].Cells[e.ColumnIndex].ToolTipText = "This record is updated";

                        string strPreviousValue = "";
                        string strNewValue = "";

                        // -- FOR HIGHLIGHTING DEDUCTEE PAN
                        //CHECKING IF THE PAN IS UPDATED

                        strPreviousValue = Convert.ToString(dgcViewSalaryDetails.Rows[e.RowIndex].Cells["HDR_EMPLOYEE_PAN"].Value);
                        strNewValue = Convert.ToString(dgcViewSalaryDetails.Rows[e.RowIndex].Cells["EMPLOYEE_PAN"].Value);

                        if (strPreviousValue != strNewValue)
                        {
                            dgcViewSalaryDetails.Rows[e.RowIndex].Cells["EMPLOYEE_PAN"].Style.BackColor = Color.Yellow;
                            dgcViewSalaryDetails.Rows[e.RowIndex].Cells["EMPLOYEE_PAN"].ToolTipText = "Old Value\t: " + strPreviousValue +
                                                                                             "\nNew Value\t: " + strNewValue;
                        }

                        #endregion

                    }

                    else if (e.Value.ToString() == "Add")
                    {
                        e.CellStyle.BackColor = Color.LightGreen;
                        dgcViewSalaryDetails.Rows[e.RowIndex].Cells["MODE"].ToolTipText = "New Record Added";
                    }

                    else if (e.Value.ToString() == "Del")
                    {
                        e.CellStyle.BackColor = Color.FromArgb(231, 206, 248);
                        dgcViewSalaryDetails.Rows[e.RowIndex].Cells["MODE"].ToolTipText = "This record is marked for deletion.\n";
                    }
                }
                #endregion
            }
            catch (Exception err)
            {
            }
        }
        #endregion

