                                ////dblTaxPaid = cmnService.J_ReturnDoubleValue(txtTotalTaxDeductedAmt.Text);// +dblTaxSuperannuationFund; //-- 2016/09/26
                                //dblTaxPaid = cmnService.J_ReturnDoubleValue(txtTotalTDSDedcuted.Text);
                                
                                // Now comparing Tax Paid with Tax to be paid.
                                if(cmnService.J_ReturnDoubleValue(txtTotalTDSDedcuted.Text) < cmnService.J_ReturnDoubleValue(lblTaxPayable.Text))
                                //if (dblTaxPaid < dblTotalTaxTobePaid)
