                            //-- RETRIEVE MODE FROM COR_TRN_SALARY_DETAILS
                            //------------------------------------------------------------------
                            strSQL = "SELECT MODE FROM COR_TRN_SALARY_DETAILS WHERE TRN_SALARY_DETAILS_ID = " + lngSearchId;
                            //-- 
                            //------------------------------------------------------------------
                            //------------------------------------------------------------------
                            #region [ MODE -> DELETED  ]
                            //-- WHILE MODE-- [ DELETED ] 
                            if (Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)) == T_CorrectionMode.Delete)
                            {
                                if (cmnService.J_UserMessage("Are you sure you want to restore this record?", MessageBoxButtons.YesNo) == DialogResult.Yes)
                                {
                                    //Restoring the deleted data
                                    strSQL = " UPDATE COR_TRN_SALARY_DETAILS " +
                                             " SET    MODE                  = '' " +
                                             " WHERE  TRN_SALARY_DETAILS_ID = " + lngSearchId + "";

                                    if (dmlService.J_ExecSql(strSQL) == false)
                                    {
                                        lblMode.Text = J_Mode.Add;
                                        //txtDeducteeName.Select();
                                        return;
                                    }
                                }
                                else return;
                            }
                            #endregion
                            //------------------------------------------------------------------
                            #region [  Mode - > UPDATED  ]
                            //------------------------------------------------------------------
                            else
                            {
                                if (cmnService.J_UserMessage("Are you sure you want to restore this record to its original values?", MessageBoxButtons.YesNo) == DialogResult.Yes)
                                {
                                    // SETTING MODE OF THE RECORD AS PAN_UPDATE_INDICATOR IS ON AND INITIALISING MODIFIED VALUES
                                    strSQL = "UPDATE COR_TRN_SALARY_DETAILS " +
                                             "INNER JOIN COR_HDR_SALARY_DETAILS " +
                                             "       ON  COR_TRN_SALARY_DETAILS.HDR_SALARY_DETAILS_ID      = COR_HDR_SALARY_DETAILS.HDR_SALARY_DETAILS_ID  " +
                                             "SET    COR_TRN_SALARY_DETAILS.MODE                           = '', " +
                                             "       COR_TRN_SALARY_DETAILS.PAN_UPDATION_INDICATOR         =  " + T_UPDATION_INDICATOR.OFF + ",            " +
                                             "       COR_TRN_SALARY_DETAILS.EMPLOYEE_PAN                   = COR_HDR_SALARY_DETAILS.EMPLOYEE_PAN           " +
                                             " WHERE COR_TRN_SALARY_DETAILS.TRN_SALARY_DETAILS_ID          = " + lngSearchId + "";
                                    if (dmlService.J_ExecSql(strSQL) == false)
                                    {
                                        lblMode.Text = J_Mode.Add;
                                        //txtDeducteeName.Select();
                                        return;
                                    }
                                }
                                else return;
                            }
