                        else if (BtnDelete.Text == T_DeleteRestoreText.Delete)
                        {
                            //-----------------------------------------------------------
                            dmlService.J_BeginTransaction();
                            //-- ANIK - 2017-02-24 - FROM FVU 5.4
                            strSQL = @"SELECT MODE 
                                       FROM   COR_TRN_SALARY_DETAILS 
                                       WHERE  TRN_SALARY_DETAILS_ID = " + lngSearchId;
                            if (Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)) == T_CorrectionMode.Form26A_27BA &&
                                cmnService.J_ReturnInt64Value(txtFAYearID.Text.Trim()) >= T_FinancialYearID.F2007_08ID)
                            {
                                cmnService.J_UserMessage("Modification/Deletion not allowed as Form 26A/27BA has been generated by IT Dept.");
                                lblMode.Text = J_Mode.Add;
                                dmlService.J_Rollback();
                                return;
                            }
                            //--
                            //-----------------------------------------------------------
                            //-- CHECK THE TRANSACTION
                            //-----------------------------------------------------------------------
