        #region LoadSalaryDetailsGrid

        #region LoadSalaryDetailsGrid
        private void LoadSalaryDetailsGrid(long BatchHeaderID)
        {
            //-----------------------------------------------------------
            string[,] strMatrixSalaryDetails = {{"SalaryDetailsID", "0", "", "Right", "", "F", ""},
                                                {"Srl No.", "35", "0", "", "", "", ""},
                                                {"Mode", "50", "S", "", "", "", ""},
                                                {"PAN", "90", "S", "", "", "", ""},
                                                {"Name", "160", "S", "", "", "", "T"},
                                                {"Total Deducted", "85", "0.00", "R", "", "", ""},
                                                {"Old Pan", "85", "S", "R", "", "F", ""},
                                                {"Invalid Pan", "85", "0", "R", "", "F", ""},
                                                {"Pan Update", "85", "0", "R", "", "F", ""}};
            //-----------------------------------------------------------
            //strMatrix = strMatrix1;
            //-----------------------------------------------------------
            /* (1) Column Value
             * (2) Column Data Type
             * (3) Replace String
             * (4) Replace String Data Type */
            //-----------------------------------------------------------
            //-----------------------------------------------------------
            string[,] strLoadSDMode = {{"COR_TRN_SALARY_DETAILS.MODE = 'U'", "F", "Upd", "T"},
                                        {"COR_TRN_SALARY_DETAILS.MODE = 'A'", "F", "Add", "T"},
                                        {"COR_TRN_SALARY_DETAILS.MODE = 'D'", "F", "Del", "T"},
                                        {"COR_TRN_SALARY_DETAILS.MODE = 'O'", "F", "New", "T"},
                                        {"COR_TRN_SALARY_DETAILS.PAN_UPDATION_INDICATOR = 1", "F", "Upd", "T"},
                                        {"COR_TRN_SALARY_DETAILS.MODE = ''", "F", "", "T"}};
            //
            strOrderBy = "COR_TRN_SALARY_DETAILS.TRN_SALARY_DETAILS_ID";
            strQuery = "SELECT COR_TRN_SALARY_DETAILS.TRN_SALARY_DETAILS_ID  AS TRN_SALARY_DETAILS_ID," +
                       "       COR_TRN_SALARY_DETAILS.SL_NO                  AS SL_NO," +
                       "       " + cmnService.J_SQLDBFormat(strLoadSDMode, J_SQLColFormat.Case_End) + " AS MODE," +
                       "       COR_TRN_SALARY_DETAILS.EMPLOYEE_PAN           AS EMPLOYEE_PAN," +
                       "       COR_TRN_SALARY_DETAILS.EMPLOYEE_NAME          AS EMPLOYEE_NAME," +
                       "       COR_TRN_SALARY_DETAILS.TOTAL_TDS_DEDUCTED     AS TOT_TDS_DEDUCTED," +
                       "       COR_HDR_SALARY_DETAILS.EMPLOYEE_PAN           AS HDR_EMPLOYEE_PAN," +
                       "       COR_HDR_SALARY_DETAILS.INVALID_PAN            AS INVALID_PAN," +
                       "       COR_TRN_SALARY_DETAILS.PAN_UPDATION_INDICATOR AS PAN_UPDATION_INDICATOR " +
                       "FROM   COR_TRN_SALARY_DETAILS " +
                       "LEFT JOIN COR_HDR_SALARY_DETAILS " +
                       "       ON COR_TRN_SALARY_DETAILS.HDR_SALARY_DETAILS_ID = COR_HDR_SALARY_DETAILS.HDR_SALARY_DETAILS_ID " +
                       "WHERE  COR_TRN_SALARY_DETAILS.BATCH_HEADER_ID  = " + BatchHeaderID + " ";
            //-----------------------------------------------------------
            strSQL = strQuery + "ORDER BY " + strOrderBy;
            //-----------------------------------------------------------
            if (dsetGridClone != null) dsetGridClone.Clear();
            dsetGridClone = dmlService.J_ShowDataInGrid(ref  dgcViewSalaryDetails, strSQL, strMatrixSalaryDetails);       //Show Data into the Grid
        }
        #endregion

