                       "LEFT JOIN COR_HDR_SALARY_DETAILS " +
                       "       ON COR_TRN_SALARY_DETAILS.HDR_SALARY_DETAILS_ID = COR_HDR_SALARY_DETAILS.HDR_SALARY_DETAILS_ID " +
                       "WHERE  COR_TRN_SALARY_DETAILS.BATCH_HEADER_ID  = " + BatchHeaderID + " ";
            //-----------------------------------------------------------
            strSQL = strQuery + "ORDER BY " + strOrderBy;
            //-----------------------------------------------------------
            if (dsetGridClone != null) dsetGridClone.Clear();
            dsetGridClone = dmlService.J_ShowDataInGrid(ref  dgcViewSalaryDetails, strSQL, strMatrixSalaryDetails);       //Show Data into the Grid
        }
        #endregion

