                        }
                        //
                        if (TdsMan.T_IsExcelDatabaseObjectExist("PAN Error SD", T_PanErrorAnnexSheet.SrNo, con) == false)
                        {
                            con.Close();
                            con.Dispose();
                            return false;
                        }
                        if (TdsMan.T_IsExcelDatabaseObjectExist("PAN Error SD", T_PanErrorAnnexSheet.SDSerialNo, con) == false)
                        {
                            con.Close();
                            con.Dispose();
                            return false;
                        }
                        if (TdsMan.T_IsExcelDatabaseObjectExist("PAN Error SD", T_PanErrorAnnexSheet.PANofEmployee, con) == false)
                        {
                            con.Close();
                            con.Dispose();
                            return false;
                        }
                        if (TdsMan.T_IsExcelDatabaseObjectExist("PAN Error SD", T_PanErrorAnnexSheet.NameOfEmployee, con) == false)
                        {
                            con.Close();
                            con.Dispose();
                            return false;
                        }
                        if (TdsMan.T_IsExcelDatabaseObjectExist("PAN Error SD", T_PanErrorAnnexSheet.NewPAN, con) == false)
                        {
                            con.Close();
                            con.Dispose();
                            return false;
                        }
                        //--
                    }
                    #endregion

                    //-- Added By Abhishek Dey On 21/11/2018 --
                    #region Bulk Deletion
                    else if (rbnBulkDeletion.Checked == true)
                    {
                        if (TdsMan.T_IsExcelDatabaseObjectExist("Data for Bulk Deletion SD", null, con) == false)
                        {
                            con.Close();
                            con.Dispose();
                            return false;
                        }
                        //
                        if (TdsMan.T_IsExcelDatabaseObjectExist("Data for Bulk Deletion SD", T_BulkDeletionSheetSD.SDSerialNo, con) == false)
                        {
                            con.Close();
                            con.Dispose();
                            return false;
                        }

                        if (TdsMan.T_IsExcelDatabaseObjectExist("Data for Bulk Deletion SD", T_BulkDeletionSheetSD.PAN, con) == false)
                        {
                            con.Close();
                            con.Dispose();
                            return false;
                        }

                        if (TdsMan.T_IsExcelDatabaseObjectExist("Data for Bulk Deletion SD", T_BulkDeletionSheetSD.Name, con) == false)
                        {
                            con.Close();
                            con.Dispose();
                            return false;
                        }

                        if (TdsMan.T_IsExcelDatabaseObjectExist("Data for Bulk Deletion SD", T_BulkDeletionSheetSD.TotalDeducted, con) == false)
                        {
                            con.Close();
                            con.Dispose();
                            return false;
                        }

                    }
                        #endregion
                }
                //-----------------------------------------
                return true;

            }
            catch (Exception err)
            {
                cmnService.J_UserMessage(err.Message);
                con.Close();
                return false;
            }

        }
