                                if (strSD_SERIAL_NO == "" &&
                                             strPARTY_PAN == "" &&
                                                    strPARTY_NEW_PAN == "")
                                    break;
                                //
                                cmnService.J_WriteLine(ref StreamWriterDeductee, TdsMan.T_WriteField(intLineNumberSalary.ToString()) +
                                TdsMan.T_WriteField(strSERIAL_NO) +
                                TdsMan.T_WriteField((Convert.ToString((char)(intColumnValue + 2)) + (Convert.ToString(intLineNumberSalary + 1)))) + TdsMan.T_WriteField(strSD_SERIAL_NO) +
