                        myCommand = new OleDbDataAdapter("SELECT * FROM [Data for Bulk Deletion SD$]", con);
                        //
                        myCommand.Fill(myDataSet);
                        //
                        long lngRow = 2;
                        long lngColumn = 0;
                        int intLineNumber = 0;
                        string strSERIAL_NO = string.Empty;

                        //
                        if (myDataSet.Tables[0].Rows.Count > 0)  //-- Added By Abhishek Dey On 12/10/2018 --
                        {
                            #region INSERTING DATA TO TEXT FILE

                            foreach (DataRow myDataRow in myDataSet.Tables[0].Rows)
                            {
                                //Stores info in Datarow into an array
                                Object[] cells = myDataRow.ItemArray;

                                int intColumnValue = 63;

                                intLineNumber = intLineNumber + 1;

                                long lngColumnIndex = 0;
                                //

                                strSERIAL_NO = PopulateSerial.NextSerial(strSalaryDetailsSerialNo_401).ToString();
                                strSDSerialNo = Convert.ToString(cells[lngColumnIndex++]).ToUpper();
                                strEmployeePan = Convert.ToString(cells[lngColumnIndex++]).ToUpper();
                                strEmployeeOfName = Convert.ToString(cells[lngColumnIndex++]).ToUpper();
                                strTotalTaxDeducted = Convert.ToString(cells[lngColumnIndex++]).ToUpper();
                                if (!string.IsNullOrEmpty(strTotalTaxDeducted))    //-- Added By Abhishek Dey On 04/10/2018 --                          
                                    strTotalTaxDeducted = string.Format("{0:0.00}", Convert.ToDouble(strTotalTaxDeducted));
                                //-- 10/10/2018 --
                                if (strSDSerialNo == "" &&
                                       strEmployeePan == "" &&
                                            strEmployeeOfName == "" &&
                                                 strTotalTaxDeducted == "")
                                    break;
                                //--
                                cmnService.J_WriteLine(ref StreamWriterDeductee, TdsMan.T_WriteField(intLineNumber.ToString()) +
                                TdsMan.T_WriteField(strSDSerialNo) +
                                TdsMan.T_WriteField((Convert.ToString((char)(intColumnValue + 2)) + (Convert.ToString(intLineNumber + 1)))) + TdsMan.T_WriteField(strEmployeePan) +
                                TdsMan.T_WriteField((Convert.ToString((char)(intColumnValue + 3)) + (Convert.ToString(intLineNumber + 1)))) + TdsMan.T_WriteField(strEmployeeOfName) +
                                TdsMan.T_WriteField((Convert.ToString((char)(intColumnValue + 4)) + (Convert.ToString(intLineNumber + 1)))) + TdsMan.T_WriteField(strTotalTaxDeducted) +
                                TdsMan.T_WriteField((Convert.ToString((char)(intColumnValue + 5)) + (Convert.ToString(intLineNumber + 1)))));

                            }

                            myDataSet.Dispose();
                            myCommand.Dispose();
                            //}
                            con.Close();
                            con.Dispose();

                            StreamWriterDeductee.Flush();
                            StreamWriterDeductee.Close();

                            #endregion

                            int NumberOfLines = 0;
                            //
                            #region TRANSFERRING TO DATA FROM TEXT TO ACCESS

                            //string tableName = "";
                            //string textfileName = "";
                            //TABLE NAME TO HOLD DATA
                            tableName = "" + TDSMAN.Classes.TDSMAN.T_tblTEMP_SD_DELETE + "";

                            //TEXT FILE NAME
                            //textfileName = "ModifyPAN";
                            textfileName = TDSMAN.Classes.TDSMAN.T_pProductSerial + "_SDDelete";  //-- Modified By Abhishek Dey On 09/07/2018 --

                            TdsMan.T_ReplaceDoubleQuotesinFile(strTemporaryfileSalaryPath, true);

                            ImportTextToTables(tableName, textfileName, strTemporaryfileSalaryPath, false);

                            // DELETE THE TXT FILE
                            if (File.Exists(strTemporaryfileSalaryPath) == true)
                                File.Delete(strTemporaryfileSalaryPath);

                            #endregion

                        }
                        else
                        {
                            cmnService.J_UserMessage("No records found!", MessageBoxButtons.OK, MessageBoxIcon.Error);
                            return false;
                        }

                        #endregion
                    }
                    //-----------------------------------------
                }
                con.Close();
                con.Dispose();
                //
                intLN = 0;
                return true;
                //############################################
            }
            catch
            {
                return false;
            }
        }
