                                      {"" + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".GROSS_TOTAL_INC = ''" , "F", "0", "F"}};

                //--------------------------------------------
                strSQL = "INSERT INTO COR_TRN_SALARY_DETAILS (" +
                        "             BATCH_HEADER_ID," +
                        "             EMPLOYEE_NAME," +
                        "             EMPLOYEE_PAN," +
                        "             EMPLOYEE_CATEGORY," +
                        "             FROM_DATE," +
                        "             TO_DATE," +
                        "             TS_BALANCE," +
                        "             US_16_EA," +
                        "             US_16_TE," +
                        "             US_16_AGGREGATE," +
                        "             INCOME_CHARGEABLE," +
                        "             AIS_Total," +
                        "             GROSS_TOTAL_INCOME," +
                        "             CVIA_SEC80CCE_TOTAL_DED_AMOUNT,";

                ////## Anik 2013/04/25
                if (Convert.ToInt32(txtFAYearID.Text) == T_FinancialYearID.F2010_11ID || Convert.ToInt32(txtFAYearID.Text) == T_FinancialYearID.F2011_12ID)
                    strSQL = strSQL + "CVIA_SEC80CCF_DED_AMOUNT,";
                else //if (Convert.ToInt32(Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex)) >= T_FinancialYearID.F2012_13ID)
                    strSQL = strSQL + "CVIA_SEC80CCG_DED_AMOUNT,";
                //--
                strSQL = strSQL + "CVIA_OTH_DED_TOTAL," +
                    "             CVIA_DED_TOTAL," +
                    "             TOTAL_INCOME," +
                    "             TAX_TOTAL_INCOME," +
                    "             SCHG_TOTAL_INCOME," +
                    "             ECESS_TOTAL_INCOME," +
                    "             US_89_LESS," +
                    "             TAX_PAYABLE," +
                    "             TOTAL_TDS_DEDUCTED," +
                    "             SHORTFALL_TAX," +
                    "             TAXABLE_AMOUNT," +
                    "             REPORTED_TAXABLE_AMOUNT," +
                    "             TOTAL_TAX_DEDUCTED_AMOUNT," +
                    "             PREVIOUS_TAX_DEDUCTED_TOTAL," +
                    "             TAX_DEDUCTED_HIGHER_RATE," +
                    "             SL_NO, " +
                    "             EXCEL_IMPORT_FLAG, " +
                    "             MODE," +
                    "             SUPER_ANN_YN, " +
                    "             SUPER_ANN_NAME, " +
                    "             SUPER_ANN_FROM_DATE, " +
                    "             SUPER_ANN_TO_DATE, " +
                    "             SUPER_ANN_AMOUNT, " +
                    "             SUPER_ANN_RATE, " +
                    "             SUPER_ANN_TAX, " +
                    "             SUPER_ANN_INCOME ";
                if (Convert.ToInt32(txtFAYearID.Text) >= T_FinancialYearID.F2016_17ID)
                    strSQL = strSQL + " ,RENT_EXCEEDING_YN, " +
                    "             LANDLORD_PAN_COUNT, " +
                    "             LANDLORD_1_PAN, " +
                    "             LANDLORD_1_NAME, " +
                    "             LANDLORD_2_PAN, " +
                    "             LANDLORD_2_NAME, " +
                    "             LANDLORD_3_PAN, " +
                    "             LANDLORD_3_NAME, " +
                    "             LANDLORD_4_PAN, " +
                    "             LANDLORD_4_NAME, " +
                    "             INTEREST_PAID_TO_LENDER, " +
                    "             LENDER_PAN_COUNT, " +
                    "             LENDER_1_PAN, " +
                    "             LENDER_1_NAME, " +
                    "             LENDER_2_PAN, " +
                    "             LENDER_2_NAME, " +
                    "             LENDER_3_PAN, " +
                    "             LENDER_3_NAME, " +
                    "             LENDER_4_PAN, " +
                    "             LENDER_4_NAME ";
                strSQL = strSQL + ") " +
                    "   SELECT    " + lngBatchId + "," +
                    "             RTRIM(EMPLOYEE_NAME)," +
                    "             EMPLOYEE_PAN," +
                    "             CATEGORY,";
